package gemini

import (
	"os"
	"path/filepath"
	"testing"
)

func TestParseNetscapeCookies(t *testing.T) {
	raw := `# Netscape HTTP Cookie File
# https://curl.se/docs/http-cookies.html
# This file was generated by libcurl! Edit at your own risk.

.google.com	TRUE	/	TRUE	1773000000	SAPISID	test_sapisid_123
#HttpOnly_.google.com	TRUE	/	TRUE	1773000000	__Secure-1PSID	test_psid_456
evil.com	TRUE	/	FALSE	1773000000	EVIL	should_not_be_included
`
	cookieStr := ParseNetscapeCookies(raw)
	pairs := parseCookiePairs(cookieStr)

	if pairs["SAPISID"] != "test_sapisid_123" {
		t.Errorf("expected SAPISID test_sapisid_123, got %q", pairs["SAPISID"])
	}
	if pairs["__Secure-1PSID"] != "test_psid_456" {
		t.Errorf("expected __Secure-1PSID test_psid_456, got %q", pairs["__Secure-1PSID"])
	}
	if _, ok := pairs["EVIL"]; ok {
		t.Errorf("expected non-google cookie to be excluded")
	}
}

func TestCookieStoreLoadNetscape(t *testing.T) {
	tmpDir := t.TempDir()
	cookieFile := filepath.Join(tmpDir, "cookies.txt")
	content := "# Netscape HTTP Cookie File\n.google.com\tTRUE\t/\tTRUE\t1773000000\tSAPISID\tmysapisid\n"
	if err := os.WriteFile(cookieFile, []byte(content), 0600); err != nil {
		t.Fatalf("failed to write test cookie file: %v", err)
	}

	cs := &CookieStore{}
	cookieStr, sapisid := cs.Load(cookieFile)
	if sapisid != "mysapisid" {
		t.Errorf("expected sapisid mysapisid, got %q", sapisid)
	}
	if cookieStr != "SAPISID=mysapisid" {
		t.Errorf("expected cookieStr 'SAPISID=mysapisid', got %q", cookieStr)
	}
}
